import{_ as o,a as t}from"./chunks/42999b305c2f845f4644.BX7h_m15.js";import{_ as r,C as l,o as s,c as i,j as e,a as n,E as c,a6 as f}from"./chunks/framework.CnPv4DE1.js";const v=JSON.parse('{"title":"成功的人不寻求建议：为什么99%的人会失败","description":"","frontmatter":{"title":"成功的人不寻求建议：为什么99%的人会失败","originalTitle":"Successful People Don’t Ask For Advice (Why 99% Of People Fail)","date":"2023-08-12","originalUrl":"https://thedankoe.com/letters/successful-people-dont-ask-for-advice-why-99-of-people-fail/","minutes":12,"sourceHash":"ef7fc0d23ec78ff758a21c75ee94917860855628bfa31b0ab914998f51788c6a","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/successful-people-dont-ask-for-advice-why-99-of-people-fail/"}]]},"headers":[],"relativePath":"letters/successful-people-dont-ask-for-advice-why-99-of-people-fail.md","filePath":"letters/successful-people-dont-ask-for-advice-why-99-of-people-fail.md"}'),d={name:"letters/successful-people-dont-ask-for-advice-why-99-of-people-fail.md"};function h(m,p,u,g,_,k){const a=l("ArticleMeta");return s(),i("div",null,[p[0]||(p[0]=e("h1",{id:"成功的人不寻求建议-为什么99-的人会失败",tabindex:"-1"},[n("成功的人不寻求建议：为什么99%的人会失败 "),e("a",{class:"header-anchor",href:"#成功的人不寻求建议-为什么99-的人会失败","aria-label":'Permalink to "成功的人不寻求建议：为什么99%的人会失败"'},"​")],-1)),c(a),p[1]||(p[1]=f('<p><a href="https://www.youtube.com/embed/pK02W9y8PYo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>“我该怎么创业？”</p><p>“我该怎么开始和人交谈？”</p><p>“我该怎么开始追求我的目标？”</p><p>直接开始。</p><p>（寻求建议并不是开始）。</p><p>寻求建议会让你变蠢。</p><p>大多数人之所以寻求建议，是因为他们害怕经历其他人为了实现目标而经历过的尴尬和失败。</p><p>别误会，建议并不总是坏事。</p><p>但如果99%不成功的人问了99%的建议……也许这里面藏着一个教训。</p><p>这就是为什么关于“如何创业”或“如何练出六块腹肌”的书籍和信息汗牛充栋，而99%的人依然会失败。</p><p>而且，人们寻求的99%的建议都太模糊了，<em>根本不可能</em>回答。问这种问题简直就是浪费时间。</p><p>“我该怎么创业？”</p><p>啊，对对对，让我写上四本书，把我的整个人生旅程写下来，再把为你量身定制的100个YouTube视频重做一遍，这样你就不需要做任何努力了。</p><p>去写你自己的书。</p><p>去过你自己的人生。</p><p>别再坐着干那些无法提升你经验值的事情了。</p><p>出于对学习旅程的恐惧而将整个旅程外包出去，你永远无法得到真正可执行的答案。</p><p>问题在于缺乏理解。</p><p>人们不明白如何学习。</p><p>他们从未坐下来思考过学习的过程是什么样的。</p><p>大多数人甚至从未寻求过关于如何学习的建议（我的意思是：人们从一开始就问错了问题）。</p><p>当他们面对一个新目标时，并没有将学习过程作为制定决策的框架：</p><ol><li>确立一个有意识、有意义的目标</li><li>开始养成能够实现该目标的习惯</li><li>管理伴随身份转变而来的痛苦和情绪</li><li>用与目标相关的信息对你的大脑进行编程</li><li>尝试各种不同的技巧</li><li>在遇到问题时寻求技术上的建议</li></ol><p>而当你进入最后一步时……建议的好坏完全取决于它是否针对你的具体情况。</p><p>书籍、播客、文章和社交媒体内容中都有很好的建议，但其中只有0.001%适用于你所处的<em>具体</em>情况。在你生命中的这个瞬间能感知到的数百万比特信息，在下一秒就会截然不同（并且与任何其他人的经验以及他们对这种经验的解释完全不同）。</p><p>只有当你处于痛苦、挣扎或面对挑战的状态时，你才能获得跃升到下一层次所需的洞察力。</p><p>获得最佳建议是需要一个过程的。</p><p>这样你就不会因为吸收了无用的知识而导致大脑“超重”。</p><p>让我们来剖析一下身份转变、自我实验，以及如何寻求建议，从而让你的学习实现超级加速：</p><h2 id="你不需要更多的建议-你需要改变自己" tabindex="-1">你不需要更多的建议，你需要改变自己 <a class="header-anchor" href="#你不需要更多的建议-你需要改变自己" aria-label="Permalink to &quot;你不需要更多的建议，你需要改变自己&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>你没有实现某个目标的原因是，你还不是那个能够实现该目标的人。</p><p>你设定的每一个新目标，都像是在向未知领域抛下沉锚。</p><p>你设定的每一个新目标都要求你具备新的世界观、特定的技能以及重塑你自我的信念。</p><p>就像打电子游戏一样。</p><p>你没有达到100级是有原因的。</p><p>你缺乏将你变成100级的角色发展历程。</p><p>在电子游戏中，风险不是真实的。</p><p>在现实生活中，风险是真实的，但往往被我们的想法过度放大了。</p><p>所有的改变都需要身份的转变。</p><p>你不能指望仅仅听取建议就能为你提供实现你所设定目标水平所需的经验。</p><p>你上一次<em>真正</em>听取你所寻求的建议是什么时候？</p><p>在所有你得到的建议中，你实际上听进去了多少？</p><p>你得到的大多数建议并不适用于你当前的目标水平和认知水平。</p><p>一个100级的人会告诉你对他们来说很合理的东西，但对于一个10级的人来说却毫无意义。</p><p>人们没有意识到，经验的差异是呈指数级增长的。</p><p>在游戏中，每升一级都需要更多的经验。</p><p>从10级升到11级可能需要300点经验值。</p><p>从99级升到100级则需要100倍于此的经验值。</p><p>作为一个新手，你不需要改变太多。你改变几个习惯，每天腾出一个小时，你就能在一年（左右）的时间内取代你现在的收入。</p><p>在那之后，真正的自我发展之旅才算开始。进步会放缓，就像健身房里的“新手福利期”现象一样。在第一年，你的力量和肌肉会迅速增长，但随后就会变成缓慢而痛苦的煎熬。</p><p>如果你的身份认同里不包含耐心、长期主义、能够承受风险并且热爱失败，你就会输掉。</p><p><strong>1) 为你的世界观编程</strong></p><p>你的世界观影响着你视角的开放程度。</p><p>你视角的开放程度影响着你对各种情况的感知。</p><p>你对情况的感知影响着你做出的决策。</p><p>你做出的决策影响着你的行为方式。</p><p>你的行为形成一个信息反馈循环，这个循环为你的身份或自我意识进行编程。</p><p>你的身份塑造了你的世界观，而你的世界观又反过来塑造了你的身份。</p><p>你该如何开始改变自己？</p><p>通过将自我教育和技能获取视为日常生活中必不可少的一部分。</p><p>让我感到困惑的是，很少有人这样做。</p><p>他们想成为一个更好的人。</p><p>他们想成就伟业。</p><p>他们想获得内心的平静。</p><p>但他们没有意识到，他们向这些理想结果迈进的能力，源于具备这样做的技能。</p><p>技能，是大脑与生活的交汇处。</p><p>技能是通过教育和实践培养出来的。</p><p>你所处的位置和你想要达到的目标之间的差距，就是技能。不是信念。不是知识。不是环境。不是社会经济地位。不是你的成长背景。所有这些都是变量，虽然强大，但终究敌不过技能。</p><p>这一切都要从为你的大脑输入正确的信息开始。</p><p>把漫无目的地刷手机换成有意识的学习。</p><p>把打电子游戏换成构建新项目（一样的道理，只是在现实世界里）。</p><p>把睡懒觉换成晨走，以及能为你的人生开启新可能性的书籍、播客或视频。</p><p>学习会让你觉察到机会。对机会的觉察会产生动力。随着时间的推移，持续学习（每天坚持不懈）会改变你的决策方式。</p><p><strong>2) 身份转变的痛苦</strong></p><p>改变自己就像雕刻一件艺术品。</p><p>到了18岁时，你就像一块巨大、方正的大理石板，看起来、摸起来和表现出来都很粗糙丑陋。</p><p>第一个决定是最痛苦的。</p><p>那就是致力于改变的决心。</p><p>强行从大理石里*崩*出一条胳膊，这样你才能开始雕刻。</p><p>现在要小心了。</p><p>如果你敲击得太重，可能会毁掉整块石板。</p><p>你必须用微小、精准的敲击，来雕刻出你理想的精神体格。</p><p>每一次境遇都是你可以进行的一次微小敲击。</p><p>你必须有意识地应对各种情况。</p><p>当你感到一阵焦虑袭来时，停顿一下，然后坚持扛过去。</p><p>痛苦是暂时的。</p><p>所有的成长都需要痛苦。</p><p><strong>3) 痛苦即快乐，死亡孕育生命</strong></p><p>我这周在听弗兰克·杨（Frank Yang）以前的一个<a href="https://youtu.be/nJGJICvcf4k" target="_blank" rel="noreferrer">天台漫谈（Roof Talk）视频</a>。</p><p>在我十几岁的时候，我会听这些东西，但完全不知道他在说什么（我只是想用深奥的知识让自己显得古怪又睿智，好在朋友面前装酷）。</p><p>他提出了一个关于死亡的有趣观点。</p><p>如果死亡就是终极真相呢？</p><p>去与当下的一切融为一体。</p><p>去消除所有的精神束缚，以及自我与本源之间的屏障。</p><p>我们有两种驱力（正如弗洛伊德所说）：</p><ul><li><strong>性驱力</strong> —— 创造、生存，并在母体（matrix）中延续我们的生命</li><li><strong>死亡驱力</strong> —— 毁灭、绝对化，并回归无限</li></ul><p>我会在下一封信中讨论这些（为什么你无法逃离母体），但弗兰克的观点是这样的。</p><p>我们享受痛苦，但许多人逃避痛苦，转而用那些表面上令人愉悦、能让你保持“舒服”的活动来施加更多、难以忍受的痛苦。</p><p>有些人在健身房、商业活动以及个人发展中寻找它。他们褪去层层的自我，尽可能地接近一种精神上的死亡 —— 那是僧侣、神秘主义者和自我提升者的目标。</p><p>这里的教训是，创造一个环境（比如健身房），来制造那种能孕育新生命的苦难。</p><p>我不认为绝对的自我死亡是答案，所以我不会在这里讨论它。</p><p>并且，请理解我说的不是一种物理上或唯物主义范式上的死亡。我指的是精神上的。象征性的。</p><h2 id="自我实验的力量-如何一劳永逸地解决你的问题" tabindex="-1">自我实验的力量（如何一劳永逸地解决你的问题） <a class="header-anchor" href="#自我实验的力量-如何一劳永逸地解决你的问题" aria-label="Permalink to &quot;自我实验的力量（如何一劳永逸地解决你的问题）&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>自我实验是一劳永逸解决你问题的唯一途径。</p><p>自我实验和自力更生相辅相成。它们互为养分。</p><p>自我实验是你避开处方式教条和方法论建议之危险本质的方法。</p><p>一个假设的问题：</p><p>没有足够的钱把时间花在自己喜欢做的事情上。</p><p>Person A:</p><p>完全照着理财大师说的做。</p><p>他们开始在这里投点小钱，在那里投点小钱。</p><p>他们投资股票时走稳妥路线。</p><p>他们换了更便宜的车，这样就省去了每月的开销。</p><p>Person B:</p><p>从多个渠道汲取建议，自己做决定。</p><p>他们会借鉴方法论建议，但目的只是为了发现在追求目标时可以融入其中的底层原则。</p><p>他们虔诚地学习，但绝不依附于那些让他们停滞不前的商业、健康或社会意识形态。</p><p>最终，通过学习和努力，他们灵光乍现，瞬间*顿悟*，懂得了该如何把事情做成。</p><p>我最近在Instagram上看到一个帖子，说财富积累是一个缓慢的过程，对此我同意，但也没那么慢。</p><p>那个帖子说，每一个30岁以下成为百万富翁的人，要么靠继承遗产，要么有极高收入，要么遇到了能带来巨额收入的事件（比如加密货币）。</p><p>分享这个帖子的人提到，自己也继承了遗产，而且一直在精打细算，但到了三十好几，离赚到一百万的目标才走到一半。</p><p>我说这些是为了提供个视角，在26岁时我就成了一名拥有百万流动资产的富翁（后来我把其中的50%投资到了一项新业务中），而我经营的是一家年营收达350万美元的一人企业（one-person business）。</p><p>没人能教我怎么做……因为以前很少有人走过我走的路。就在几年前，这甚至还是一种不可能。是技术让它成为了可能，而极少有人抓住了这个机会。</p><p>我教不了<em>具体的</em>路径，因为这具有高度的个体差异性。</p><p>当然，我可以教授原则，为你提供系统，并在像<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>和<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>这样的项目中向你展示我是怎么做的地图 —— 但就算是这样，你仍然需要通过学习和努力才能让它为你所用。</p><p>让我们来看看实现你所下定决心要达成的任何目标的一些具体步骤：</p><p><strong>1) 确立一个有意识的目标</strong></p><p>目标为你制定决策提供了一个框架。</p><p>我不想听到你拾人牙慧，把从詹姆斯·克莱尔（James Clear）那里听来的“系统重于目标！”的建议再重复一遍。</p><p>没有目标，你就不可能有系统。就这么简单。</p><p>你需要一个能够成长为愿景的目标。</p><p>一个你时刻牢记在心的目标，这样你就能为该目标带给你的动力收集燃料。</p><p>你不会凭空就感到动力十足。</p><p>你带着目标生活，体验人生，并通过学习和观察产生实现该目标的<em>理由</em>。</p><p>你对一个目标投入的能量（教育和努力）越多，这个目标的引力就越强。它开始毫不费力地把你拉向它。</p><p><strong>2) 整体理解</strong></p><p>大局大于技术细节。</p><p>原则大于战术。</p><p>但这并不意味着就不需要技术细节和战术了（就像系统不能消除对目标的需要一样）。</p><p>如果你不了解你试图建立的业务中的每一个运转环节，你在商业上就会失败。</p><p>如果你对自己的身体、营养和训练没有一个整体的了解，你在健身上就会失败。</p><p>而且，如果你不了解环境、现代食物和压力的巨大负面影响——你就会屈服于它们。</p><p>觉察力能让做出积极的决定变得容易得多。</p><p>如果你对希望实现的目标没有大局观的理解，你就容易受到意识形态的影响，而在一个相对的世界里，从意识形态的定义来看，它们就是不真实的。</p><p>你会掉进一夜暴富的骗局、狂热的节食法和严苛的建议之中，当你意识到它们不可持续时，只能从头再来。</p><p>当你朝着一个目标迈进时，教育和努力是齐头并进的，它们共同创造理解。</p><ul><li>购买各类通识书籍，收听播客，关注那些输出各种观点的社交媒体账号。</li><li>利用你所拥有的时间去追求你的目标，并把你学到的东西付诸实践。行动能巩固真正的知识。</li><li>随着学习不断调整你的决策。一开始你会做得很烂。这是任何新尝试的现实。</li></ul><p><strong>3) 尝试各种技巧</strong></p><p>当你在通往目标的道路上不断学习时，你会发现一些可以去测试的技巧。</p><p>在商业中，这就像是写作建议、获客建议、最佳商业模式，以及任何你通过谷歌快速搜索就能找到的东西。</p><p>这些都是任何人都可以（也会）去追求的唾手可得的信息。</p><p>如果它很容易找到，那么你很可能不会成为一个特别的成功案例。</p><p>我希望能给出具体的建议，但那会让你面临同样的问题。</p><p>还是那句话，自力更生。</p><p>你必须去<em>尝试</em>别人给你的技巧，这样你才能通过经验学到背后的原则。</p><p>当你了解到真相时，新的机会（别人看不到的）就会在你面前显现。</p><p>如果我没有7次创业失败的经历，我绝对不会考虑成为一名创作者。</p><p>我也不会看到它巨大的好处。</p><p>我也不可能把它做成（因为<a href="/letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money">我没有常青的技能栈</a>）。</p><p>你通过尝试各种技巧来增加你的技能栈。</p><p>技能会产生复利，并让你能够察觉并抓住更好的机会。</p><p><strong>4) 将有效的方法系统化</strong></p><p>当你对自己想做的事情越来越清晰时，会出现一些为你带来最大回报的“杠杆”。</p><p>某些技巧能让你获得比别人好1%的结果。那就是你的优势。因为那1%会产生复利。</p><p>我可以每天早上写30分钟，并将这些内容重新利用发布到所有平台。正是这个做法（随着时间的推移）给我带来了数百万的粉丝和美元。</p><p>我把写作视为获取流量的杠杆。</p><p>我把新闻信看作是一种可以无限重复利用的内容。</p><p>一开始这花了我很长时间，但随着我技能的提高，我能够将其系统化，把时间缩减到每天早上30分钟。</p><p>对于一个初学者来说，情况不会是这样的。</p><p>在社交媒体之类的地方，你必须：</p><ul><li>像疯子一样回复，吸引别人来关注你的账号和内容</li><li>练习撰写能被分享（并能带来粉丝）的内容</li><li>打造一个解决你自己问题的产品或服务</li><li>开始撰写长篇内容以建立信任并实现销售</li></ul><p>你的系统将会进化和改变。</p><p>如果它们没有变化，你就会错失增长机会。</p><p>我依然认识一些拥有10万粉丝的人（他们赚的钱比我少5-10倍），因为他们不知道如何进化自己的系统。</p><p>他们依然每天浪费1-2个小时去评论，而不是去构建他们愿景的下一个层面。随着你的成长，这会成为一个巨大的时间黑洞（我不想听任何粉丝少于5万的人的意见，你既不懂也没有经验）。</p><p>这封信可能不是最具实操性的，但这正是重点。</p><p>对于每一个给出的可执行建议，都有10万人永远无法从中获得成功。</p><p>所以，别再对着“全是干货，毫无废话”自慰了，你恰恰需要这些“废话”来建立细致入微的理解。</p><p>不要成为建议瘾君子。</p><p>做你想做的事，并通过教育和努力在这方面做得更好。</p><p>周末愉快。</p><p>– Dan</p><hr><p><a href="/en/letters/successful-people-dont-ask-for-advice-why-99-of-people-fail">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',187))])}const y=r(d,[["render",h]]);export{v as __pageData,y as default};
